const config = {
    "previewFeatures": [],
    "clientVersion": "7.8.0",
    "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
    "activeProvider": "postgresql",
    "inlineSchema": "// Prisma schema — Lexi backend\n// Docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider            = \"prisma-client\"\n  output              = \"../generated/prisma\"\n  moduleFormat        = \"cjs\"\n  importFileExtension = \"\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────────────────────\n// Enums\n// ─────────────────────────────────────────────────────────────\n\nenum AuthProvider {\n  LOCAL\n  GOOGLE\n}\n\nenum CefrLevel {\n  A1\n  A2\n  B1\n  B2\n  C1\n  C2\n}\n\nenum TtsVoice {\n  EN_US\n  EN_GB\n}\n\nenum WordStatus {\n  NEW\n  LEARNING\n  MASTERED\n}\n\nenum ConversationStatus {\n  ACTIVE\n  COMPLETED\n}\n\n// Which \"Ask Lexi\" surface a saved chat thread belongs to.\nenum ChatKind {\n  TUTOR\n  GRAMMAR\n}\n\nenum QuizStatus {\n  IN_PROGRESS\n  COMPLETED\n}\n\nenum NotificationType {\n  REVIEW_DUE\n  STREAK_RISK\n  ENCOURAGEMENT\n  BADGE_EARNED\n  SYSTEM\n}\n\nenum UserRole {\n  LEARNER\n  ADMIN\n}\n\n// Conversation-scenario difficulty (UI maps to Dễ / Trung bình / Khó).\nenum ScenarioDifficulty {\n  EASY\n  MEDIUM\n  HARD\n}\n\n// Every write action an admin can take, recorded in the audit log (UCA08).\nenum AuditAction {\n  CREATE\n  UPDATE\n  DELETE\n  LOCK\n  UNLOCK\n  TOGGLE\n  IMPORT\n  EXPORT\n}\n\n// ─────────────────────────────────────────────────────────────\n// Auth & user\n// ─────────────────────────────────────────────────────────────\n\nmodel User {\n  id            String       @id @default(cuid())\n  email         String       @unique\n  passwordHash  String? // null for social logins\n  provider      AuthProvider @default(LOCAL)\n  emailVerified Boolean      @default(false)\n  role          UserRole     @default(LEARNER)\n\n  // Brute-force protection: lock the account after too many failed logins.\n  failedLoginAttempts Int       @default(0)\n  lockedUntil         DateTime?\n\n  // Admin-imposed account lock (UCA06). Distinct from the brute-force\n  // `lockedUntil`: null = active; set = an admin disabled the account and the\n  // user cannot log in until unlocked.\n  disabledAt     DateTime?\n  disabledReason String?\n\n  lastActiveAt DateTime @default(now())\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  auditLogs AuditLog[]\n\n  setting           Setting?\n  streak            Streak?\n  words             Word[]\n  grammarRules      GrammarRule[]\n  reviewLogs        ReviewLog[]\n  quizResults       QuizResult[]\n  conversationLogs  ConversationLog[]\n  chatThreads       ChatThread[]\n  notifications     Notification[]\n  userBadges        UserBadge[]\n  pushSubscriptions PushSubscription[]\n  refreshTokens     RefreshToken[]\n\n  @@map(\"users\")\n}\n\n// Rotating refresh tokens for cookie-based auth. Only the SHA-256 hash of the\n// opaque token is stored, so a DB leak can't reconstruct a usable token. Each\n// refresh rotates: the old row is marked revoked and a new one is issued.\nmodel RefreshToken {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String    @unique // SHA-256 of the raw token\n  expiresAt DateTime\n  revokedAt DateTime? // set on rotation, logout, or reuse-detection\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel Setting {\n  id            String    @id @default(cuid())\n  userId        String    @unique\n  user          User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  dailyGoal     Int       @default(10) // words per day\n  cefrLevel     CefrLevel @default(A2)\n  topics        String[]  @default([])\n  reminderTime  String    @default(\"20:00\") // \"HH:mm\" in the user's `timeZone`\n  timeZone      String    @default(\"Asia/Ho_Chi_Minh\") // IANA tz for reminderTime\n  notifyEnabled Boolean   @default(true)\n  ttsVoice      TtsVoice  @default(EN_US)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@map(\"settings\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// Vocabulary + SRS\n// ─────────────────────────────────────────────────────────────\n\nmodel Word {\n  id             String     @id @default(cuid())\n  userId         String\n  user           User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  term           String\n  meaning        String\n  phonetic       String?\n  partOfSpeech   String?\n  examples       String[]   @default([])\n  synonyms       String[]   @default([])\n  antonyms       String[]   @default([])\n  topic          String?\n  note           String?\n  status         WordStatus @default(NEW)\n  // UC11 quiz rotation: true once this word has been quizzed in the current\n  // coverage cycle. Reset for all of a user's words when the cycle completes.\n  quizzedInCycle Boolean    @default(false)\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  srsData    SrsData?\n  reviewLogs ReviewLog[]\n\n  @@unique([userId, term]) // prevent duplicates in a user's book\n  @@index([userId, status])\n  @@map(\"words\")\n}\n\n// SM-2 spaced-repetition state, 1-1 with Word.\nmodel SrsData {\n  id             String    @id @default(cuid())\n  wordId         String    @unique\n  word           Word      @relation(fields: [wordId], references: [id], onDelete: Cascade)\n  interval       Int       @default(1) // days until next review\n  easeFactor     Float     @default(2.5)\n  repetitions    Int       @default(0)\n  lastQuality    Int? // 0..5, last self-rated recall\n  lastReviewedAt DateTime?\n  nextReviewAt   DateTime  @default(now())\n\n  @@index([nextReviewAt])\n  @@map(\"srs_data\")\n}\n\nmodel ReviewLog {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  wordId     String\n  word       Word     @relation(fields: [wordId], references: [id], onDelete: Cascade)\n  quality    Int // 0..5\n  reviewedAt DateTime @default(now())\n\n  @@index([userId, reviewedAt])\n  @@index([wordId])\n  @@map(\"review_logs\")\n}\n\n// Reference list of common TOEIC vocabulary (global, not per-user). Used to\n// verify/mark which AI-suggested synonyms are actually TOEIC-frequent words\n// (UC21). Seeded from prisma/data/toeic-vocab.csv; add rows over time.\nmodel ToeicWord {\n  id        String   @id @default(cuid())\n  term      String   @unique // normalized: lowercased, trimmed, no trailing \"(...)\"\n  display   String? // original surface form from the source list\n  pos       String? // part of speech, e.g. \"n\", \"v\", \"adj\"\n  ipa       String? // phonetic transcription\n  meaning   String? // Vietnamese meaning\n  group     String? // admin-assigned theme, e.g. \"Kinh doanh\", \"Tài chính\"\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"toeic_words\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// Admin: conversation scenarios + audit log\n// ─────────────────────────────────────────────────────────────\n\n// Bank of speaking scenarios learners pick in UC12. Managed by admins (UCA04);\n// `enabled=false` hides it from the picker without deleting it.\nmodel ConversationScenario {\n  id          String             @id @default(cuid())\n  name        String             @unique\n  description String\n  roleHint    String // opening role/context handed to the AI\n  difficulty  ScenarioDifficulty @default(EASY)\n  enabled     Boolean            @default(true)\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n\n  @@map(\"conversation_scenarios\")\n}\n\n// Append-only trail of every admin write action (UCA08). Read-only from the UI.\n// The acting admin is kept both as a nullable FK and an email snapshot so the\n// record survives even if that admin account is later removed.\nmodel AuditLog {\n  id         String      @id @default(cuid())\n  adminId    String?\n  admin      User?       @relation(fields: [adminId], references: [id], onDelete: SetNull)\n  adminEmail String // snapshot of the acting admin's email at write time\n  action     AuditAction\n  target     String // human-readable object, e.g. \"Từ: forecast\"\n  reason     String?\n  before     String?\n  after      String?\n  createdAt  DateTime    @default(now())\n\n  @@index([adminId])\n  @@index([action])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// Grammar\n// ─────────────────────────────────────────────────────────────\n\nmodel GrammarRule {\n  id          String   @id @default(cuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title       String?\n  formula     String\n  explanation String\n  examples    String[] @default([])\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([userId])\n  @@map(\"grammar_rules\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// Quiz\n// ─────────────────────────────────────────────────────────────\n\nmodel QuizResult {\n  id          String     @id @default(cuid())\n  userId      String\n  user        User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  score       Int        @default(0)\n  total       Int\n  status      QuizStatus @default(IN_PROGRESS)\n  questions   Json? // generated questions + user answers (for resume/review)\n  createdAt   DateTime   @default(now())\n  completedAt DateTime?\n\n  @@index([userId, createdAt])\n  @@map(\"quiz_results\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// AI skills — conversation practice\n// ─────────────────────────────────────────────────────────────\n\nmodel ConversationLog {\n  id         String             @id @default(cuid())\n  userId     String\n  user       User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  scenario   String\n  transcript Json               @default(\"[]\") // [{ role, content, feedback? }]\n  feedback   String? // final strengths/weaknesses summary\n  status     ConversationStatus @default(ACTIVE)\n  createdAt  DateTime           @default(now())\n  updatedAt  DateTime           @updatedAt\n\n  @@index([userId])\n  @@map(\"conversation_logs\")\n}\n\n// A saved \"Ask Lexi\" / \"Grammar Q&A\" chat thread. The AI ask endpoints stay\n// stateless; the client owns the running transcript and persists it here so a\n// learner can browse and reopen past chats across devices.\nmodel ChatThread {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  kind      ChatKind\n  title     String\n  messages  Json     @default(\"[]\") // client-shaped turns: [{ who, text, … }]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, kind, updatedAt])\n  @@map(\"chat_threads\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// Gamification\n// ─────────────────────────────────────────────────────────────\n\nmodel Streak {\n  id             String    @id @default(cuid())\n  userId         String    @unique\n  user           User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  currentStreak  Int       @default(0)\n  longestStreak  Int       @default(0)\n  streakFreezes  Int       @default(0) // \"protect streak\" items\n  lastActiveDate DateTime?\n\n  @@map(\"streaks\")\n}\n\nmodel Badge {\n  id          String   @id @default(cuid())\n  code        String   @unique // stable identifier, e.g. \"first_word\"\n  name        String\n  description String\n  condition   String // human-readable rule; evaluated in code\n  icon        String?\n  createdAt   DateTime @default(now())\n\n  userBadges UserBadge[]\n\n  @@map(\"badges\")\n}\n\nmodel UserBadge {\n  id       String   @id @default(cuid())\n  userId   String\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  badgeId  String\n  badge    Badge    @relation(fields: [badgeId], references: [id], onDelete: Cascade)\n  earnedAt DateTime @default(now())\n\n  @@unique([userId, badgeId])\n  @@index([userId])\n  @@map(\"user_badges\")\n}\n\n// ─────────────────────────────────────────────────────────────\n// Notifications\n// ─────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id      String           @id @default(cuid())\n  userId  String\n  user    User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  content String\n  type    NotificationType @default(SYSTEM)\n  read    Boolean          @default(false)\n  sentAt  DateTime         @default(now())\n\n  @@index([userId, read])\n  @@map(\"notifications\")\n}\n\n// Web Push subscription (one per device/browser).\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n",
    "runtimeDataModel": {
        "models": {},
        "enums": {},
        "types": {}
    },
    "parameterizationSchema": {
        "strings": [],
        "graph": ""
    }
};
